WITH AccountSummary AS (SELECT account_id, ROUND((100 * SUM(CASE WHEN merchant = 'Amazon' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_amazon FROM transactions GROUP BY account_id) SELECT a.id, a.balance, A.pct_amazon FROM accounts a JOIN AccountSummary A ON a.id = A.account_id WHERE A.pct_amazon >= 56;
